{
  "section": "configuration",
  "available_sections": [
    {
      "id": "core",
      "description": "Required Python/signal rules and revision lifecycle."
    },
    {
      "id": "research",
      "description": "Required research choices, defaults and explicit inheritance."
    },
    {
      "id": "evidence",
      "description": "Parameter proposals, source claims and saved trading formulas."
    },
    {
      "id": "indicators",
      "description": "Installed indicator catalog and selected API/source reference."
    },
    {
      "id": "example",
      "description": "Complete Python and YAML example to adapt."
    },
    {
      "id": "configuration",
      "description": "Full execution YAML schema and metric settings."
    },
    {
      "id": "runtime",
      "description": "Generated isolation, resource policy and failure recovery."
    }
  ],
  "content": {
    "config_schema": {
      "$defs": {
        "AutomaticWalkForwardConfig": {
          "additionalProperties": false,
          "description": "Rolling or expanding windows computed from the available row count.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "default": 0,
              "description": "Forward label bars; zero disables the fold leakage audit.",
              "minimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "automatic",
              "title": "Mode",
              "type": "string"
            },
            "n_splits": {
              "default": 1,
              "minimum": 1,
              "title": "N Splits",
              "type": "integer"
            },
            "train_ratio": {
              "default": 0.8,
              "exclusiveMaximum": 1,
              "exclusiveMinimum": 0,
              "title": "Train Ratio",
              "type": "number"
            },
            "expanding": {
              "default": false,
              "title": "Expanding",
              "type": "boolean"
            }
          },
          "required": [
            "mode"
          ],
          "title": "AutomaticWalkForwardConfig",
          "type": "object"
        },
        "BacktestConfig": {
          "additionalProperties": false,
          "description": "Backtest execution configuration.",
          "properties": {
            "symbol": {
              "title": "Symbol",
              "type": "string"
            },
            "timeframe": {
              "title": "Timeframe",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "init_cash": {
              "anyOf": [
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Init Cash"
            },
            "fees": {
              "default": 0.0006,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "default": 0.0005,
              "title": "Slippage",
              "type": "number"
            },
            "position_size": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Position Size"
            },
            "stop_loss": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Stop Loss"
            },
            "take_profit": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Take Profit"
            },
            "signal_as_position": {
              "default": false,
              "description": "Volume mode only: true makes signal=0 close an existing position; false retains it while preventing new entries. Signal mode always uses position states (1 long, -1 short, 0 flat) and ignores this flag. In both modes -1 selects short, not a sell-only exit.",
              "title": "Signal As Position",
              "type": "boolean"
            },
            "re_entry_after_sl": {
              "default": true,
              "title": "Re Entry After Sl",
              "type": "boolean"
            },
            "mode": {
              "default": "signal",
              "enum": [
                "signal",
                "volume"
              ],
              "title": "Mode",
              "type": "string"
            },
            "monthly_max_loss": {
              "default": 1500.0,
              "description": "Volume mode only; requires timestamps. Quote-currency loss limit for each UTC calendar month. Compare cumulative P&L equity with the previous observed month's last close equity (zero in the first month). Missing months are not filled; gaps belong to the next observed month. Count current-month costs and unrealised P&L changes, not prior-month P&L or entry costs again. Trade records retain whole-trade P&L and costs. Check after stop exits before re-entry and after ordinary trading at close. Reaching the loss limit closes any remaining position at close and pauses until the next observed month; exit costs may exceed the limit.",
              "title": "Monthly Max Loss",
              "type": "number"
            },
            "periods_per_year": {
              "anyOf": [
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Periods Per Year"
            },
            "risk_free_rate": {
              "default": 0.0,
              "exclusiveMinimum": -1,
              "title": "Risk Free Rate",
              "type": "number"
            },
            "required_return": {
              "default": 0.0,
              "exclusiveMinimum": -1,
              "title": "Required Return",
              "type": "number"
            }
          },
          "required": [
            "symbol",
            "timeframe",
            "start_date",
            "end_date"
          ],
          "title": "BacktestConfig",
          "type": "object"
        },
        "ExplicitWalkForwardConfig": {
          "additionalProperties": false,
          "description": "One training/test pair, with inclusive nonoverlapping UTC calendar days.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "default": 0,
              "description": "Forward label bars; zero disables the fold leakage audit.",
              "minimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "explicit",
              "title": "Mode",
              "type": "string"
            },
            "train_start": {
              "format": "date-time",
              "title": "Train Start",
              "type": "string"
            },
            "train_end": {
              "format": "date-time",
              "title": "Train End",
              "type": "string"
            },
            "test_start": {
              "format": "date-time",
              "title": "Test Start",
              "type": "string"
            },
            "test_end": {
              "format": "date-time",
              "title": "Test End",
              "type": "string"
            }
          },
          "required": [
            "mode",
            "train_start",
            "train_end",
            "test_start",
            "test_end"
          ],
          "title": "ExplicitWalkForwardConfig",
          "type": "object"
        },
        "ParallelConfig": {
          "additionalProperties": false,
          "description": "Parallel execution configuration.",
          "properties": {
            "reserve_cores": {
              "default": 2,
              "title": "Reserve Cores",
              "type": "integer"
            },
            "safety_factor": {
              "default": 0.6,
              "title": "Safety Factor",
              "type": "number"
            },
            "overhead_multiplier": {
              "default": 3.0,
              "exclusiveMinimum": 0,
              "title": "Overhead Multiplier",
              "type": "number"
            }
          },
          "title": "ParallelConfig",
          "type": "object"
        },
        "PurgedWalkForwardConfig": {
          "additionalProperties": false,
          "description": "Anchored expanding windows with label purge and an optional extra embargo.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "description": "Required positive forward label horizon in bars.",
              "exclusiveMinimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "purged",
              "title": "Mode",
              "type": "string"
            },
            "n_splits": {
              "default": 1,
              "minimum": 1,
              "title": "N Splits",
              "type": "integer"
            },
            "embargo_bars": {
              "default": 0,
              "minimum": 0,
              "title": "Embargo Bars",
              "type": "integer"
            }
          },
          "required": [
            "label_horizon",
            "mode"
          ],
          "title": "PurgedWalkForwardConfig",
          "type": "object"
        },
        "ResearchMetadata": {
          "additionalProperties": false,
          "description": "Origins of resolved fields, never a proof that a human supplied the input.",
          "properties": {
            "schema_version": {
              "const": 1,
              "default": 1,
              "title": "Schema Version",
              "type": "integer"
            },
            "policy_version": {
              "minLength": 1,
              "title": "Policy Version",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "field_sources": {
              "additionalProperties": {
                "enum": [
                  "request",
                  "project_default",
                  "selected_revision"
                ],
                "type": "string"
              },
              "title": "Field Sources",
              "type": "object"
            },
            "selected_revision": {
              "anyOf": [
                {
                  "$ref": "#/$defs/ResearchRevisionIdentity"
                },
                {
                  "type": "null"
                }
              ],
